  var overlay = document.getElementById('pbOverlay');

  function openPb() { drawer.classList.add('open'); overlay.classList.add('open'); if (window.__mtRefreshBodyScrollLock) window.__mtRefreshBodyScrollLock(); else document.body.style.overflow = 'hidden'; }
  function closePb() { drawer.classList.remove('open'); overlay.classList.remove('open'); if (window.__mtRefreshBodyScrollLock) window.__mtRefreshBodyScrollLock(); else document.body.style.overflow = ''; }

  /* ── DRAG ── */
  var isDragging = false;
  var didDrag = false;
  var startX, startY, startLeft, startTop;

  function getPos() {
    var r = openBtn.getBoundingClientRect();
    return { left: r.left, top: r.top };
  }

  function onDragStart(e) {
    var clientX = e.touches ? e.touches[0].clientX : e.clientX;
    var clientY = e.touches ? e.touches[0].clientY : e.clientY;
    var pos = getPos();
    startX = clientX; startY = clientY;
    startLeft = pos.left; startTop = pos.top;
    isDragging = true; didDrag = false;
    openBtn.classList.add('dragging');
    openBtn.style.animation = 'none';
    openBtn.style.bottom = 'auto';
    openBtn.style.left = startLeft + 'px';
    openBtn.style.top = startTop + 'px';
    e.preventDefault();
  }

  function onDragMove(e) {
    if (!isDragging) return;
    var clientX = e.touches ? e.touches[0].clientX : e.clientX;
    var clientY = e.touches ? e.touches[0].clientY : e.clientY;
    var dx = clientX - startX;
    var dy = clientY - startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) didDrag = true;
    var newLeft = Math.max(8, Math.min(window.innerWidth - openBtn.offsetWidth - 8, startLeft + dx));
    var newTop  = Math.max(8, Math.min(window.innerHeight - openBtn.offsetHeight - 8, startTop + dy));
    openBtn.style.left = newLeft + 'px';
    openBtn.style.top  = newTop + 'px';
    e.preventDefault();
  }

  function onDragEnd(e) {
    if (!isDragging) return;
