(function () {
    var root = document.getElementById('gtkDrawerRoot');
    var backdrop = document.getElementById('gtkDrawerBackdrop');
    var dialog = document.getElementById('gtkDrawerDialog');
    var openBtn = document.getElementById('gtkOpenBtn');
    var closeBtn = document.getElementById('gtkDrawerClose');
    var titleEl = document.getElementById('gtkDrawerTitle');
    var leadEl = document.getElementById('gtkDrawerLead');
    var listEl = document.getElementById('gtkDrawerList');
    var moreBtn = document.getElementById('gtkDrawerMoreBtn');
    var ctaEl = document.getElementById('gtkDrawerCta');
    var errEl = document.getElementById('gtkDrawerError');
    if (!root || !dialog || !openBtn || !titleEl || !leadEl || !listEl) return;

    var countryKey = (document.body.getAttribute('data-good-to-know-country') || '').trim() || 'SK';
    var openedAt = 0;
    var prevFocus = null;
    var GTK_JSON = 'good-to-know-by-country.json';
    var COLLAPSE_AFTER = 4;
    var expandedItems = false;

    function getCategoryMeta(item) {
      var id = (item && item.id ? item.id : '').toLowerCase();
      if (id.indexOf('etias') > -1 || id.indexOf('entry') > -1 || id.indexOf('schengen') > -1) return { icon: '🛂', chip: 'כניסה' };
      if (id.indexOf('esim') > -1 || id.indexOf('sim') > -1 || id.indexOf('internet') > -1) return { icon: '📶', chip: 'קישוריות' };
      if (id.indexOf('transport') > -1 || id.indexOf('drive') > -1 || id.indexOf('road') > -1) return { icon: '🚗', chip: 'תחבורה' };
      if (id.indexOf('weather') > -1 || id.indexOf('season') > -1) return { icon: '🌦️', chip: 'מזג אוויר' };
      if (id.indexOf('budget') > -1 || id.indexOf('money') > -1 || id.indexOf('cost') > -1) return { icon: '💶', chip: 'תקציב' };
      if (id.indexOf('packing') > -1 || id.indexOf('gear') > -1 || id.indexOf('bag') > -1) return { icon: '🎒', chip: 'ציוד' };
      return { icon: '💡', chip: 'תכנון' };
    }

    function applyCollapse() {
      var items = listEl.querySelectorAll('.gtk-drawer__item');
      if (!items.length) { if (moreBtn) moreBtn.hidden = true; return; }
      var needsCollapse = items.length > COLLAPSE_AFTER;
      for (var i = 0; i < items.length; i++) items[i].hidden = needsCollapse && !expandedItems && i >= COLLAPSE_AFTER;
      if (moreBtn) {
        moreBtn.hidden = !needsCollapse;
        moreBtn.setAttribute('aria-expanded', expandedItems ? 'true' : 'false');
        moreBtn.textContent = expandedItems ? 'הצג פחות' : 'הצג עוד טיפים';
      }
    }

    function setError(msg) {
      if (!errEl) return;
      if (msg) { errEl.textContent = msg; errEl.hidden = false; }
      else { errEl.textContent = ''; errEl.hidden = true; }
    }

    function renderFromEntry(entry) {
      setError('');
      titleEl.textContent = entry.title_he || 'טוב לדעת';
      leadEl.textContent = entry.lead_he || '';
      listEl.innerHTML = '';
      expandedItems = false;
      var items = entry.items || [];
      items.forEach(function (item) {
        if (!item || !item.tips_url) return;
        var meta = getCategoryMeta(item);
        var li = document.createElement('li');
        li.className = 'gtk-drawer__item';
        var a = document.createElement('a');
        a.className = 'gtk-drawer__card';
        a.href = item.tips_url;
        a.setAttribute('rel', 'noopener');
        a.dataset.cardId = item.id || '';
        a.dataset.cardTitle = item.title_he || '';
        a.dataset.cardCategory = meta.chip || '';
        a.dataset.cardPosition = String(listEl.children.length + 1);
        var t = document.createElement('span');
        t.className = 'gtk-drawer__card-title';
        t.textContent = item.title_he || '';
        var headrow = document.createElement('span');
        headrow.className = 'gtk-drawer__headrow';
        var icon = document.createElement('span');
        icon.className = 'gtk-drawer__icon';
        icon.textContent = meta.icon;
        icon.setAttribute('aria-hidden', 'true');
        var chip = document.createElement('span');
        chip.className = 'gtk-drawer__chip';
        chip.textContent = meta.chip;
        var s = document.createElement('span');
        s.className = 'gtk-drawer__card-summary';
        s.textContent = item.summary_he || '';
        var m = document.createElement('span');
        m.className = 'gtk-drawer__card-more';
        m.textContent = 'להמשך קריאה ←';
        headrow.appendChild(icon);
        headrow.appendChild(t);
        headrow.appendChild(chip);
        a.appendChild(headrow);
        a.appendChild(s);
        a.appendChild(m);
        li.appendChild(a);
        listEl.appendChild(li);
      });
      applyCollapse();
      if (!listEl.children.length) setError('אין פריטים מוגדרים ליעד זה. נסו שוב מאוחר יותר או עברו לדף הטיפים.');
    }

    function renderFallback(msg) {
      titleEl.textContent = 'טוב לדעת';
      leadEl.textContent = 'לא הצלחנו לטעון את הרשימה מהשרת. אפשר עדיין לפתוח את מרכז התכנון והעמודים המקושרים מהדף הראשי.';
      listEl.innerHTML = '';
      if (moreBtn) moreBtn.hidden = true;
      setError(msg || 'שגיאת טעינה.');
    }

    function loadJson() {
      fetch(GTK_JSON, { credentials: 'same-origin' })
        .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function (data) {
          var entry = data && data[countryKey];
          if (!entry) { renderFallback('לא נמצאה רשימה למפתח המדינה "' + countryKey + '".'); return; }
          renderFromEntry(entry);
        })
        .catch(function () { renderFallback('לא ניתן לטעון את הקובץ כרגע (בדיקת חיבור או נתיב לקובץ).'); });
    }

    loadJson();

    listEl.addEventListener('click', function (e) {
      var a = e.target.closest('a.gtk-drawer__card');
      if (!a || !listEl.contains(a)) return;
      if (window.plausible) {
        try {
          plausible('GoodToKnow-CardClick', {
            props: {
              country: countryKey,
              href: a.getAttribute('href') || '',
              card_id: a.dataset.cardId || '',
              card_title: a.dataset.cardTitle || '',
              card_category: a.dataset.cardCategory || '',
              card_position: a.dataset.cardPosition || '',
              total_cards: String(listEl.querySelectorAll('.gtk-drawer__card').length || 0)
            }
          });
        } catch (ex) {}
      }
    });
    if (ctaEl) {
      ctaEl.addEventListener('click', function () {
        if (!window.plausible) return;
        try {
          plausible('GoodToKnow-CTA', {
            props: {
              country: countryKey,
              href: ctaEl.getAttribute('href') || 'tips.html',
              total_cards: String(listEl.querySelectorAll('.gtk-drawer__card').length || 0),
              expanded_items: expandedItems ? '1' : '0'
            }
          });
        } catch (ex) {}
      });
    }
    if (moreBtn) {
      moreBtn.addEventListener('click', function () {
        expandedItems = !expandedItems;
        applyCollapse();
        if (window.plausible) {
          try { plausible('GoodToKnow-ToggleMore', { props: { country: countryKey, expanded: expandedItems ? '1' : '0' } }); } catch (ex) {}
        }
      });
    }

    function emailOverlayOpen() {
      var el = (document.getElementById("__legacy_emailPopupOverlay") || document.createElement("div"));
      return el && el.classList.contains('open');
    }
    function lockScroll(lock) {
      if (lock) { if (!emailOverlayOpen()) document.body.style.overflow = 'hidden'; }
      else { if (!emailOverlayOpen()) document.body.style.overflow = ''; }
    }
    function getFocusables() {
      var nodes = dialog.querySelectorAll('a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])');
      return Array.prototype.slice.call(nodes).filter(function (n) {
        if (n.disabled) return false;
        var st = window.getComputedStyle(n);
        return st.visibility !== 'hidden' && st.display !== 'none';
      });
    }
    function trapKeydown(e) {
      if (e.key !== 'Tab' || !root.classList.contains('is-open')) return;
      var list = getFocusables();
      if (!list.length) return;
      var first = list[0];
      var last = list[list.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
    function openDrawer() {
      prevFocus = document.activeElement;
      root.hidden = false;
      requestAnimationFrame(function () {
        root.classList.add('is-open');
        lockScroll(true);
        openedAt = Date.now();
        openBtn.setAttribute('aria-expanded', 'true');
        if (window.plausible) { try { plausible('GoodToKnow-Open', { props: { country: countryKey } }); } catch (ex) {} }
        if (closeBtn) closeBtn.focus();
      });
    }
    function closeDrawer() {
      root.classList.remove('is-open');
      lockScroll(false);
      openBtn.setAttribute('aria-expanded', 'false');
      var t = prevFocus;
      prevFocus = null;
      if (t && typeof t.focus === 'function') t.focus();
      window.setTimeout(function () { if (!root.classList.contains('is-open')) root.hidden = true; }, 320);
    }
    openBtn.addEventListener('click', openDrawer);
    if (closeBtn) closeBtn.addEventListener('click', closeDrawer);
    if (backdrop) backdrop.addEventListener('click', function () { if (Date.now() - openedAt > 350) closeDrawer(); });
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Escape' || !root.classList.contains('is-open')) return;
      e.preventDefault();
      closeDrawer();
    }, true);
    dialog.addEventListener('keydown', trapKeydown);
    document.addEventListener('visibilitychange', function () {
      if (document.visibilityState === 'hidden' && root.classList.contains('is-open')) closeDrawer();
    });
  })();

